"""Import the native Godot fixed-layout focus graph, not a guessed spatial heuristic."""
from pathlib import Path
import json,hashlib,uuid
ROOT=Path(__file__).resolve().parents[2]
raw=ROOT/'migration/reviews/M08-collection-focus-native-v2.log'
line=next(v for v in raw.read_text().splitlines() if v.startswith('COLLECTION_FOCUS_NATIVE '))
cases=json.loads(line.removeprefix('COLLECTION_FOCUS_NATIVE '))
assert len(cases)==40
compact={key:{name:[None if states[d]['fallback'] else states[d]['focus'] for d in ['left','up','right','down']] for name,states in rows.items()} for key,rows in cases.items()}
path=ROOT/'games/xiaoyu-cocos/assets/game/CollectionFocus.ts'
path.write_text('// Generated by migration/tools/import_collection_focus.py from Godot 4.5.2.\n// Fixed original collection geometry: left, up, right, down; null falls through\n// to the original gallery shortcut. Item suffixes are visible row slots.\nexport const COLLECTION_FOCUS:Record<string,Record<string,Array<string|null>>> = '+json.dumps(compact,ensure_ascii=False,separators=(',',':'))+';\n')
meta=Path(str(path)+'.meta');meta.write_text(json.dumps({'ver':'4.0.24','importer':'typescript','imported':True,'uuid':str(uuid.uuid5(uuid.NAMESPACE_URL,'little-steps-cocos/game/CollectionFocus.ts')),'files':[],'subMetas':{},'userData':{}},indent=2)+'\n')
(ROOT/'migration/records/M08-collection-focus-native.json').write_text(json.dumps({'schema':1,'engine':'Godot 4.5.2','probe':'migration/tools/probe_collection_focus.gd','source':'games/travel_woodfish/project/travel/treasure_gallery.gd','touchButton':'framework/addons/travel_core/ui/touch_action_button.gd','rawLogSHA256':hashlib.sha256(raw.read_bytes()).hexdigest(),'layoutCount':len(cases),'directionCases':sum(len(v)*4 for v in cases.values()),'scope':'Isolated native Control/Button focus dispatch using original fixed rectangles and touch base. No graphics, runtime inventory, or whole-page proof.','cases':cases},ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'layouts':len(cases),'directions':sum(len(v)*4 for v in cases.values()),'generated':str(path)}))
